# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: inline chat for a widget that works like a function (one with a tool form, widgets.py:
#          VODs, Player usage, ...): an instruction plus the form's inputs in, new inputs
#          out. The AI only fills the form; the user runs it. Generic: the answer's shape is the
#          tool's own parameter schema (ToolForm.fill_schema) and it must pass the tool's own
#          validator (ToolForm.check), so any widget with a tool gets this with no code of its own.
#          The model also reads the chat so far, and has no tools.
# Usage: await fill(session, form, shown, instruction) -> Fill, called by State.view_event when
#        the form's "Ask AI" row is submitted (Shortcut.INLINE_EDIT opens that row). Each call is
#        one "agent" debug-log record with its usage; its cost is added to the session's.
# Spec:  spec/experimental/reflex-kernel/inline_ai.md
# ---------------------------------------------------------------------------
from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Any

from pydantic_ai import Agent, StructuredDict, capture_run_messages

from ds.util.const import DEFAULT_AI_MODEL
from ds.util.logging import log_call
from ds.util.text import clean_f_str

from . import mentions
from .session import log_usage

if TYPE_CHECKING:
    from .session import Session
    from .tool_forms import ToolForm

# times an answer that fails the tool's validator is sent back to the model to fix; after that
# the call fails (unlike code, inputs that don't validate can't be shown in the form)
MAX_FIXES = 2

_INSTRUCTIONS = clean_f_str("""
    You fill in the inputs of one tool of a Super Smash Bros. Ultimate data app, as an inline
    assistant inside the widget that shows the tool's result. You get the tool's description, the
    inputs as the form shows them now, and the user's instruction. Answer with every input: change
    what the instruction asks for and keep the rest exactly as it is now. Leave an input unset
    (null, or an empty string or list where null isn't allowed) to clear it. You can't run the tool
    or look anything up: the user reviews your inputs and runs it. Earlier messages, when there are
    any, are the user's chat with the app's assistant (its answers and tool results): use them to
    understand what the user means, eg "the player we just looked at".
    """)

fill_agent = Agent(
    DEFAULT_AI_MODEL,
    # on its Logfire spans (gen_ai.agent.name): the debug panel's Spend tab lists it apart from the chat
    name="inline-fill",
    # resolved at run time, so importing the app works without a key (as ds.ai.agent)
    defer_model_check=True,
    instructions=_INSTRUCTIONS,
)


@dataclass
class Fill:
    """What one inline chat on a form gave back."""

    inputs: dict[str, str] = field(default_factory=dict)
    """The proposed inputs as the form's fields show them (ToolForm.texts); {} when it failed."""
    error: str = ""
    usage: str = ""
    """What the call used (TurnUsage.summary), "" when it never reached the model."""
    fixes: int = 0
    """Answers sent back to the model because they failed the tool's validator."""


def prompt(form: ToolForm, shown: dict[str, str], instruction: str, note: str = "") -> str:
    """The tool, its inputs as the form shows them now, and the instruction.

    Built from parts joined by newlines (not one f-string): the description spans lines."""
    parts = [
        f"Tool: {form.title} ({form.key})",
        form.description,
        f"Inputs now (several picks are joined by commas, a ticked box is 'on'):\n{json.dumps(shown, ensure_ascii=False)}",
    ]
    if note:
        parts.append(f"The result on screen: {note}")
    parts.append(f"Instruction: {instruction}")
    return "\n\n".join(parts)


async def fill(
    session: Session | None, form: ToolForm, shown: dict[str, Any], instruction: str, note: str = ""
) -> Fill:
    """Ask the model for the form's new inputs.

    shown: the inputs as the form has them now (a submitted form), so what the user typed but
    hasn't run counts, and a second instruction refines the last proposal. note: the result's
    one-line summary. An answer the tool's validator refuses goes back to the model, up to
    MAX_FIXES times, then the call fails.
    """
    instruction = instruction.strip()
    if not instruction:
        return Fill(error="Type what to change first.")
    output_type = StructuredDict(form.fill_schema, name=form.key, description=f"The inputs of {form.title}.")
    # "@q1" in the instruction: what the variable holds goes along (mentions.py; no tools here)
    text = mentions.with_context(prompt(form, form.texts(shown), instruction, note), session)
    # the chat so far goes along (read only: the inline call is not added to the chat)
    history = list(session.ai_history) if session else []
    answer = Fill()
    used: list[Any] = []
    with log_call("agent", "inline-fill", name=f"inline fill ({form.key})", prompt=instruction) as call:
        call["added"] = mentions.context(instruction, session)
        for _ in range(MAX_FIXES + 1):
            # a capture per run: one capture only holds its first run's messages
            with capture_run_messages() as captured:
                try:
                    result = await fill_agent.run(text, message_history=history, output_type=output_type)
                except Exception as error:  # noqa: BLE001  # shown in the form's AI row, not raised into the event
                    answer.error = f"{type(error).__name__}: {error}"
                    used += captured[len(history) :]
                    break
            used += result.new_messages()
            history = result.all_messages()
            try:
                answer.inputs, answer.error = form.texts(form.check(dict(result.output))), ""
                break
            except ValueError as error:
                answer.error = f"The AI's inputs don't pass {form.title}'s check: {error}"
                answer.fixes += 1
                text = f"Those inputs fail the tool's check: {error}. Send every input again, corrected."
        if answer.error:
            call["error"] = answer.error
        call["fixes"] = answer.fixes
        usage = log_usage(call, session, used)
        if usage.requests:
            answer.usage = usage.summary()
    return answer
